def _identity_stmt(self, stmt: Statement, sctx: SchemaContext) -> None:
        """Handle identity statement."""
        if stmt.token_normalized in ("not", "not null"):
            # NOT NULL is default
            return

        sctx.current().add_column_constraint(
            ColumnConstraint.identity(stmt.token_normalized)
        )

